=== src/service/dispatchService.ts
     1	import { DispatchRun } from "../domain/notification";
     2	import { AlertPublisher } from "../messaging/eventPublisher";
     3	import { AlertConsumer } from "../notifier/consumerWorker";
     4	import { CustomerRepository } from "../repository/customerRepository";
     5	import { DeliveryLogRepository } from "../repository/deliveryLogRepository";
     6	import { OrderRepository } from "../repository/orderRepository";
     7	import { planNotifications } from "./notificationPlanner";
     8	
     9	/** 발송 회차: 미발송 이벤트 → 알림 계획 → 발행(1배치) → 소비·문자 발송 → 회차 기록 */
    10	export class DispatchService {
    11	  private lastRunId = 0;
    12	
    13	  constructor(
    14	    private readonly orders: OrderRepository,
    15	    private readonly customers: CustomerRepository,
    16	    private readonly publisher: AlertPublisher,
    17	    private readonly consumer: AlertConsumer,
    18	    private readonly log: DeliveryLogRepository,
    19	  ) {}
    20	
    21	  runOnce(): DispatchRun {
    22	    const runId = ++this.lastRunId;
    23	    const events = this.orders.takePending();
    24	    const plan = planNotifications(events, this.customers);
    25	    const pub = this.publisher.publishRun(plan.notifications);
    26	    const drained = this.consumer.drain(runId);
    27	    const run: DispatchRun = {
    28	      runId,
    29	      planned: plan.notifications,
    30	      skippedOptOut: plan.skippedOptOut,
    31	      published: pub.accepted,
    32	      batch: pub.batch,
    33	      delivered: drained.delivered,
    34	      failed: drained.failed,
    35	    };
    36	    this.log.saveRun(run);
    37	    return run;
    38	  }
    39	}
=== src/service/notificationPlanner.ts
     1	import { Notification } from "../domain/notification";
     2	import { CustomerRepository } from "../repository/customerRepository";
     3	import { PendingEvent } from "../repository/orderRepository";
     4	
     5	export interface Plan {
     6	  notifications: Notification[];
     7	  skippedOptOut: number;
     8	}
     9	
    10	/**
    11	 * 회차에 실린 주문 이벤트를 고객 알림으로 바꾼다.
    12	 *  - 수신 거부 고객은 제외한다.
    13	 *  - 같은 주문·같은 이벤트가 회차 안에 여러 번 기록됐으면(운영자 재입력 등) 한 번만 알린다.
    14	 *  - 이벤트 기록 순서를 유지한다.
    15	 */
    16	export function planNotifications(events: PendingEvent[], customers: CustomerRepository): Plan {
    17	  const seen = new Set<string>();
    18	  const notifications: Notification[] = [];
    19	  let skippedOptOut = 0;
    20	  for (const e of [...events].sort((a, b) => a.seq - b.seq)) {
    21	    const customer = customers.find(e.customerId);
    22	    if (!customer || !customer.smsOptIn) {
    23	      skippedOptOut++;
    24	      continue;
    25	    }
    26	    const id = `${e.orderNo}#${e.kind}`;
    27	    if (seen.has(id)) continue;
    28	    seen.add(id);
    29	    notifications.push({ orderNo: e.orderNo, customerId: e.customerId, kind: e.kind });
    30	  }
    31	  return { notifications, skippedOptOut };
    32	}
=== src/notifier/consumerWorker.ts
     1	import { DeliveredAlert } from "../domain/notification";
     2	import { OrderEventKind } from "../domain/order";
     3	import { MqpubClient } from "../messaging/mqpubClient";
     4	import { decodePayload } from "../messaging/payloadCodec";
     5	import { CustomerRepository } from "../repository/customerRepository";
     6	import { DeliveryLogRepository } from "../repository/deliveryLogRepository";
     7	import { SmsGateway } from "./smsGateway";
     8	import { renderAlert } from "./templates";
     9	
    10	export interface DrainResult {
    11	  read: number;
    12	  delivered: DeliveredAlert[];
    13	  failed: { orderNo: string; kind: OrderEventKind; reason: string }[];
    14	}
    15	
    16	/**
    17	 * 알림 토픽 소비자. 마지막으로 읽은 위치 다음부터 읽어 문자를 보낸다.
    18	 * 같은 키가 다시 전달되면(재처리·재기동) 두 번 보내지 않는다.
    19	 */
    20	export class AlertConsumer {
    21	  private nextOffset = 0;
    22	  private readonly handledKeys = new Set<string>();
    23	
    24	  constructor(
    25	    private readonly client: MqpubClient,
    26	    private readonly topic: string,
    27	    private readonly customers: CustomerRepository,
    28	    private readonly gateway: SmsGateway,
    29	    private readonly log: DeliveryLogRepository,
    30	    private readonly senderId: string,
    31	    private readonly limit: number,
    32	  ) {}
    33	
    34	  position(): number {
    35	    return this.nextOffset;
    36	  }
    37	
    38	  drain(runId: number): DrainResult {
    39	    const rows = this.client.consume(this.topic, this.nextOffset).slice(0, this.limit);
    40	    const result: DrainResult = { read: rows.length, delivered: [], failed: [] };
    41	    for (const row of rows) {
    42	      this.nextOffset = row.offset + 1;
    43	      if (this.handledKeys.has(row.key)) continue;
    44	      this.handledKeys.add(row.key);
    45	
    46	      const n = decodePayload(row.payload);
    47	      if (!n) {
    48	        result.failed.push({ orderNo: "?", kind: "PAID", reason: "bad-payload" });
    49	        continue;
    50	      }
    51	      const customer = this.customers.find(n.customerId);
    52	      if (!customer) {
    53	        result.failed.push({ orderNo: n.orderNo, kind: n.kind, reason: "unknown-customer" });
    54	        continue;
    55	      }
    56	      const receipt = this.gateway.send(this.senderId, customer.phone, renderAlert(n.kind, customer.name, n.orderNo));
    57	      if (!receipt.ok) {
    58	        result.failed.push({ orderNo: n.orderNo, kind: n.kind, reason: receipt.reason ?? "sms-failed" });
    59	        continue;
    60	      }
    61	      const d: DeliveredAlert = {
    62	        runId,
    63	        orderNo: n.orderNo,
    64	        customerId: n.customerId,
    65	        kind: n.kind,
    66	        phone: customer.phone,
    67	        receiptId: receipt.receiptId ?? "",
    68	      };
    69	      this.log.append(d);
    70	      result.delivered.push(d);
    71	    }
    72	    return result;
    73	  }
    74	}
