     1	export type Channel = "direct" | "market";
     2	export type OrderEventKind = "PAID" | "SHIPPED" | "DELIVERED";
     3	
     4	export interface OrderEvent {
     5	  kind: OrderEventKind;
     6	  /** 이벤트 기록 순번(앱 전역 단조 증가) */
     7	  seq: number;
     8	  dispatched: boolean;
     9	}
    10	
    11	export interface Order {
    12	  orderNo: string;
    13	  customerId: string;
    14	  channel: Channel;
    15	  partner?: string;
    16	  placedOn: string; // YYYY-MM-DD
    17	  events: OrderEvent[];
    18	}
    19	
    20	export const EVENT_KINDS: readonly OrderEventKind[] = ["PAID", "SHIPPED", "DELIVERED"];
    21	
    22	export function isEventKind(v: unknown): v is OrderEventKind {
    23	  return typeof v === "string" && (EVENT_KINDS as readonly string[]).includes(v);
    24	}
    25	
    26	/** 2026-10-07 → 261007 */
    27	export function compactDate(placedOn: string): string {
    28	  const m = /^20(\d{2})-(\d{2})-(\d{2})$/.exec(placedOn);
    29	  if (!m) throw new Error("invalid placedOn");
    30	  return `${m[1]}${m[2]}${m[3]}`;
    31	}
    32	
    33	/**
    34	 * 주문번호 체계
    35	 *   자사몰:     O<yymmdd>-<일련 5자리>            예) O261007-00042
    36	 *   오픈마켓:   M-<제휴사 4자>-<yymmdd>-<일련 6자리> 예) M-GMKT-261007-000123
    37	 */
    38	export function formatOrderNo(channel: Channel, placedOn: string, seq: number, partner?: string): string {
    39	  const d = compactDate(placedOn);
    40	  if (channel === "direct") return `O${d}-${String(seq).padStart(5, "0")}`;
    41	  if (!partner || !/^[A-Z]{4}$/.test(partner)) throw new Error("invalid partner");
    42	  return `M-${partner}-${d}-${String(seq).padStart(6, "0")}`;
    43	}
